        }
    },
    {
        "id": 3,
        "priority": 2,
        "action": {
            "type": "block"
        },
        "condition": {
            "urlFilter": "google.com/12345",
            "resourceTypes": ["main_frame"]
        }
    },
    {
        "id": 4,
        "priority": 1,
        "action": {
            "type": "redirect",
            "redirect": {
                "url": "https://example.com"
            }
        },
        "condition": {
            "urlFilter": "google.com",
            "resourceTypes": ["main_frame"]
        }
    },
    {
        "id": 5,
        "priority": 1,
        "action": {
            "type": "redirect",
            "redirect": {
                "extensionPath": "/a.jpg"
            }
        },
        "condition": {
            "urlFilter": "abcd.com",
            "resourceTypes": ["main_frame"]
        }
    },
    {
        "id": 6,
        "priority": 1,
        "action": {
            "type": "redirect",
            "redirect": {
                "transform": {
                    "scheme": "https",
