            "redirect": {
                "regexSubstitution": "https://\\1.xyz.com/"
            }
        },
        "condition": {
            "regexFilter": "^https://www\\.(abc|def)\\.xyz\\.com/",
            "resourceTypes": [
                "main_frame"
            ]
        }
    },
    {
        "id": 8,
        "priority": 2,
        "action": {
            "type": "allowAllRequests"
        },
        "condition": {
