        }
    },
    {
        "id": 10,
        "priority": 2,
        "action": {
            "type": "modifyHeaders",
            "responseHeaders": [{
                    "header": "h1",
                    "operation": "remove"
                },
                {
                    "header": "h2",
                    "operation": "set",
                    "value": "v2"
                },
                {
                    "header": "h3",
                    "operation": "append",
                    "value": "v3"
                }
            ]
        },
        "condition": {
            "urlFilter": "headers.com/123",
            "resourceTypes": ["main_frame"]
        }
    },
    {
        "id": 11,
        "priority": 1,
        "action": {
